import type { QueryRangeMapping } from "../queryRangeMapping.js";
import {
  parseBaseContinuationToken,
  type BaseContinuationToken,
  type QueryRangeWithContinuationToken,
  type RangeBoundary,
} from "../../documents/ContinuationToken/CompositeQueryContinuationToken.js";
import type {
  PartitionRangeUpdate,
  PartitionRangeUpdates,
} from "../../documents/ContinuationToken/PartitionRangeUpdate.js";
import { PartitionRangeManager, isPartitionRangeActive } from "../PartitionRangeManager.js";
import type { ParallelQueryResult } from "../parallelQueryResult.js";

/**
 * Base abstract class for continuation token management.
 * Provides common functionality shared between parallel and ORDER BY query token managers.
 * @internal
 */
export abstract class BaseContinuationTokenManager {
  private readonly ranges: QueryRangeWithContinuationToken[] = [];
  private readonly partitionRangeManager: PartitionRangeManager = new PartitionRangeManager();
  protected readonly collectionLink: string;
  protected offset?: number;
  protected limit?: number;

  constructor(collectionLink: string, initialContinuationToken?: string | BaseContinuationToken) {
    this.collectionLink = collectionLink;
    if (initialContinuationToken) {
      const token =
        typeof initialContinuationToken === "string"
          ? parseBaseContinuationToken(initialContinuationToken)
          : initialContinuationToken;
      if (token?.rangeMappings) {
        this.ranges.push(...token.rangeMappings);
      }
      this.offset = token?.offset;
      this.limit = token?.limit;
    }
  }

  /**
   * Provides controlled access to partition range manager for subclasses.
   * This is the only protected access point needed.
   */
  protected get partitionManager(): PartitionRangeManager {
    return this.partitionRangeManager;
  }

  /**
   * Provides controlled access to ranges for subclasses.
   * Made protected to allow subclass range management.
   */
  protected get rangeList(): QueryRangeWithContinuationToken[] {
    return this.ranges;
  }

  /**
   * Gets the current continuation token for serialization.
   * Returns undefined if no token exists or query is exhausted.
   */
  protected abstract getCurrentContinuationToken(): any;

  /**
   * Processes query results and generates continuation tokens for pagination.
   * Handles response data processing, range management, and token generation.
   *
   * @param pageSize - Maximum number of items to return in this page
   * @param isResponseEmpty - Whether the current response contains no data
   * @param responseResult - Optional response data containing partition mappings and query-specific data
   * @returns Object containing the end index for slicing results and optional continuation token for next page
   */
  public paginateResults(
    pageSize: number,
    isResponseEmpty: boolean,
    responseResult?: ParallelQueryResult,
    workRemains: boolean = true,
  ): {
    endIndex: number;
    continuationToken?: string;
  } {
    if (responseResult) {
      this.processResponseResult(responseResult);
    }

    this.removeExhaustedRangesFromRanges(workRemains);
    const result = this.processRangesForPagination(pageSize, isResponseEmpty, workRemains);
    const hasUnprocessedMappings =
      result.processedRanges.length < this.partitionRangeManager.getPartitionKeyRangeMap().size;
    const shouldSerializeContinuation = workRemains || hasUnprocessedMappings;
    if (!shouldSerializeContinuation) {
      this.trimProcessedData(result.processedRanges, result.endIndex);
      this.clearState();
      return { endIndex: result.endIndex };
    }
    const tokenString = this.generateContinuationTokenString();

    // Clean up processed ranges
    this.trimProcessedData(result.processedRanges, result.endIndex);

    return {
      endIndex: result.endIndex,
      continuationToken: tokenString,
    };
  }

  protected abstract processRangesForPagination(
    pageSize: number,
    isResponseEmpty: boolean,
    workRemains: boolean,
  ): {
    endIndex: number;
    processedRanges: string[];
  };

  protected abstract processQuerySpecificResponse(responseResult: ParallelQueryResult): void;
  protected abstract performQuerySpecificDataTrim(
    processedRanges: string[],
    endIndex: number,
  ): void;
  protected clearQuerySpecificState(): void {}
  protected preserveInactiveRangeCoverage(): boolean {
    return false;
  }

  /**
   * Gets the serialization function for the specific continuation token type.
   */
  protected abstract getSerializationFunction(): (token: any) => string;

  /**
   * Generates continuation token string using the appropriate serialization function.
   * This provides a common implementation that delegates to query-specific logic.
   */
  private generateContinuationTokenString(): string | undefined {
    const token = this.getCurrentContinuationToken();
    if (!token) {
      return undefined;
    }

    const serializeFunction = this.getSerializationFunction();
    return serializeFunction(token);
  }

  /**
   * Cleans up processed data after a page has been returned.
   * Handles both common and query-specific cleanup.
   */
  private trimProcessedData(processedRanges: string[], endIndex: number): void {
    processedRanges.forEach((rangeId) => {
      this.partitionRangeManager.removePartitionRangeMapping(rangeId);
    });

    // Delegate query-specific cleanup to subclass
    this.performQuerySpecificDataTrim(processedRanges, endIndex);
  }

  private clearState(): void {
    this.ranges.length = 0;
    this.partitionRangeManager.clear();
    this.offset = undefined;
    this.limit = undefined;
    this.clearQuerySpecificState();
  }

  private addPartitionKeyRangeMap(partitionKeyRangeMap: Map<string, QueryRangeMapping>): void {
    this.partitionRangeManager.addPartitionKeyRangeMap(partitionKeyRangeMap);
  }

  /**
   * Processes the entire response result and updates the continuation token manager state.
   * This encapsulates all response handling logic in one place.
   */
  private processResponseResult(responseResult: ParallelQueryResult): void {
    // Handle partition key range map
    if (responseResult.partitionKeyRangeMap) {
      this.addPartitionKeyRangeMap(responseResult.partitionKeyRangeMap);
    }

    // Handle partition range updates
    if (responseResult.updatedContinuationRanges) {
      this.handlePartitionRangeChanges(responseResult.updatedContinuationRanges);
    }

    this.processQuerySpecificResponse(responseResult);
  }

  /**
   * Compacts the ranges array in place by keeping only items that satisfy the predicate.
   * This preserves the same array reference while removing unwanted entries.
   */
  private compactRangesInPlace(
    shouldKeep: (mapping: QueryRangeWithContinuationToken) => boolean,
  ): void {
    let writeIndex = 0;
    for (let i = 0; i < this.ranges.length; i++) {
      const mapping = this.ranges[i];
      if (!shouldKeep(mapping)) {
        continue;
      }
      this.ranges[writeIndex++] = mapping;
    }
    this.ranges.length = writeIndex;
  }

  private removeExhaustedRangesFromRanges(workRemains: boolean): void {
    if (!this.ranges || !Array.isArray(this.ranges)) {
      return;
    }
    const hasActiveRange = this.ranges.some(
      (mapping) => !!mapping && isPartitionRangeActive(mapping.continuationToken, mapping.isActive),
    );
    this.compactRangesInPlace((mapping) => {
      if (!mapping) {
        return false;
      }
      if (isPartitionRangeActive(mapping.continuationToken, mapping.isActive)) {
        return true;
      }
      return (
        mapping.isOrderByCheckpoint === true ||
        ((workRemains || hasActiveRange) && this.preserveInactiveRangeCoverage())
      );
    });
  }

  private handlePartitionRangeChanges(updatedContinuationRanges: PartitionRangeUpdates): void {
    if (updatedContinuationRanges && Object.keys(updatedContinuationRanges).length === 0) {
      return;
    }
    Object.entries(updatedContinuationRanges).forEach(([rangeKey, rangeChange]) => {
      this.processRangeChange(rangeKey, rangeChange);
    });
  }

  private processRangeChange(_rangeKey: string, rangeChange: PartitionRangeUpdate): void {
    const { oldRange, newRanges, continuationToken, isActive, isOrderByCheckpoint, orderByFilter } =
      rangeChange;
    if (newRanges.length === 1) {
      this.handleRangeMerge(
        oldRange,
        newRanges[0],
        continuationToken,
        isActive,
        isOrderByCheckpoint,
        orderByFilter,
      );
    } else {
      this.handleRangeSplit(
        oldRange,
        newRanges,
        continuationToken,
        isActive,
        isOrderByCheckpoint,
        orderByFilter,
      );
    }
  }

  private handleRangeMerge(
    oldRange: any,
    newRange: any,
    continuationToken: string | undefined,
    isActive?: boolean,
    isOrderByCheckpoint?: boolean,
    orderByFilter?: QueryRangeWithContinuationToken["orderByFilter"],
  ): void {
    // Find existing range mapping to update in the common ranges array
    const existingMappingIndex = this.ranges.findIndex(
      (mapping) =>
        mapping.queryRange.min === oldRange.min && mapping.queryRange.max === oldRange.max,
    );

    if (existingMappingIndex < 0) {
      if (isActive) {
        this.createNewRangeMapping(
          newRange,
          continuationToken,
          isActive,
          isOrderByCheckpoint,
          orderByFilter,
        );
      }
      return;
    }

    // Update existing mapping with new range properties
    const existingMapping = this.ranges[existingMappingIndex];

    // Create new simplified QueryRange with updated boundaries
    const updatedQueryRange: RangeBoundary = {
      min: newRange.min,
      max: newRange.max,
    };

    // Update the mapping
    existingMapping.queryRange = updatedQueryRange;
    existingMapping.continuationToken = continuationToken;
    existingMapping.isActive = isActive;
    existingMapping.isOrderByCheckpoint = isOrderByCheckpoint;
    existingMapping.orderByFilter = this.cloneOrderByFilter(orderByFilter);
  }

  private handleRangeSplit(
    oldRange: any,
    newRanges: any[],
    continuationToken: string | undefined,
    isActive?: boolean,
    isOrderByCheckpoint?: boolean,
    orderByFilter?: QueryRangeWithContinuationToken["orderByFilter"],
  ): void {
    // Remove the old range mapping from the common ranges array (in-place, no reinitialization)
    this.compactRangesInPlace(
      (mapping) =>
        !(mapping.queryRange.min === oldRange.min && mapping.queryRange.max === oldRange.max),
    );

    // Add new range mappings for each split range
    newRanges.forEach((newRange) => {
      this.createNewRangeMapping(
        newRange,
        continuationToken,
        isActive,
        isOrderByCheckpoint,
        orderByFilter,
      );
    });
  }

  private createNewRangeMapping(
    partitionKeyRange: any,
    continuationToken: string | undefined,
    isActive?: boolean,
    isOrderByCheckpoint?: boolean,
    orderByFilter?: QueryRangeWithContinuationToken["orderByFilter"],
  ): void {
    // Create new simplified QueryRange
    const queryRange: RangeBoundary = {
      min: partitionKeyRange.min,
      max: partitionKeyRange.max,
    };

    // Create new QueryRangeWithContinuationToken
    const newRangeWithToken: QueryRangeWithContinuationToken = {
      queryRange: queryRange,
      continuationToken: continuationToken,
      isActive,
      isOrderByCheckpoint,
      orderByFilter: this.cloneOrderByFilter(orderByFilter),
    };

    this.ranges.push(newRangeWithToken);
  }

  protected cloneOrderByFilter(
    filter?: QueryRangeWithContinuationToken["orderByFilter"],
  ): QueryRangeWithContinuationToken["orderByFilter"] {
    return filter
      ? {
          orderByItems: [...filter.orderByItems],
          rid: filter.rid,
          skipCount: filter.skipCount,
        }
      : undefined;
  }
}
